            C#

    using System;

class Node {
    public int data;
    public Node next;

    public Node(int x) {
        data = x;
        next = null;
    }
}

class GfG {
    public static Node insertAtBeginning(Node last, int key) {
        Node newNode = new Node(key);

        if (last == null) {
            newNode.next = newNode;
            return newNode;
        }

        newNode.next = last.next;
        last.next = newNode;

        return last;
    }

    public static void printList(Node last) {
        if (last == null) return;

        Node head = last.next;
        Node temp = head;

        while (true) {
            Console.Write(temp.data);
            temp = temp.next;
            if (temp != head) {
                Console.Write(" -> ");
            } else {
                break;
            }
        }
        Console.WriteLine();
    }

    static void Main(string[] args) {
        // Create circular linked list: 2 -> 3 -> 4
        Node first = new Node(2);
        first.next = new Node(3);
        first.next.next = new Node(4);

        Node last = first.next.next;
        last.next = first;

        // Insert 5 at the beginning
        last = insertAtBeginning(last, 5);

        printList(last);
    }
}


            JavaScript

    class Node {
    constructor(x) {
        this.data = x;
        this.next = null;
    }
}

// Function to insert at beginning of circular linked list
function insertAtBeginning(last, key) {
    let newNode = new Node(key);

    if (last === null) {
        newNode.next = newNode;
        return newNode;
    }

    newNode.next = last.next;
    last.next = newNode;

    return last;
}

// Function to print circular linked list
function printList(last) {
    if (last === null) return;

    let head = last.next;
    let temp = head;

    while (true) {
        process.stdout.write(temp.data.toString());
        temp = temp.next;
        if (temp !== head) {
            process.stdout.write(" -> ");
        } else {
            break;
        }
    }
    console.log();
}

